'use client';

/**
 * Consumer-facing capability list for the detail page.
 *
 * The raw `skill.description` rows are evidence, not user-facing Chinese copy.
 * This component leads with 3–5 outcome statements generated by enrich-ai, and
 * keeps the original skill list behind a closed <details> block.
 */

import { useState } from 'react';
import { T } from '@/lib/dict';

export interface RawCapability {
  id: string;
  name: string;
  description: string | null;
  sourcePath: string | null;
  isVerifiedSkill: boolean;
}

export function CapabilityList({
  capabilities,
  raw,
  accent,
}: {
  capabilities: { zh: string[]; en: string[] };
  raw: RawCapability[];
  accent: string;
}) {
  const [open, setOpen] = useState(false);

  function List({ items }: { items: string[] }) {
    /* Publish already blocks rows without Chinese capability copy, so this only
       fires for un-published data. Render nothing rather than exposing an
       internal "still generating" marker to readers. */
    if (!items.length) return null;

    return (
      <ol className="grid gap-x-10 gap-y-8 md:grid-cols-2">
        {items.slice(0, 5).map((c, i) => (
          <li key={`${i}-${c}`} className="border-t border-[var(--glass-1-border)] pt-5">
            <span className="data text-[var(--ink-4)]">
              {String(i + 1).padStart(2, '0')}
            </span>
            <p className="body mt-3 max-w-[46ch] text-[var(--ink-1)]">{c}</p>
          </li>
        ))}
      </ol>
    );
  }

  return (
    <div className="mt-7">
      <div data-lang="zh">
        <List items={capabilities.zh} />
      </div>
      <div data-lang="en">
        <List items={capabilities.en} />
      </div>

      {raw.length ? (
        <div className="mt-7 border-t border-[var(--glass-1-border)] pt-6" data-lang="zh">
          <button
            type="button"
            className="system inline-flex items-center gap-3 text-[var(--ink-3)] transition-colors duration-[var(--d-micro)] hover:text-[var(--ink-1)]"
            onClick={() => setOpen((v) => !v)}
            aria-expanded={open}
          >
            <T k={open ? 'pd.what.collapse' : 'pd.what.expand'} as="span" fade={false} />
            <span aria-hidden>{open ? '−' : '+'}</span>
          </button>

          {open ? (
            <div className="mt-8" data-lang="zh">
              <T k="pd.what.raw" as="p" className="system text-[var(--ink-4)]" fade={false} />
              <ul className="mt-5 flex flex-col">
                {raw.map((s) => (
                  <li
                    key={s.id}
                    className="flex flex-col gap-2 border-t border-[var(--glass-1-border)] py-5 md:flex-row md:items-baseline md:gap-8"
                  >
                    <div className="md:w-72 md:shrink-0">
                      <p className="body text-[var(--ink-1)]">{s.name}</p>
                      {s.isVerifiedSkill ? (
                        <p className="system mt-2" style={{ color: accent }}>
                          <T k="pd.what.verified" as="span" fade={false} />
                        </p>
                      ) : null}
                    </div>
                    <div className="min-w-0 flex-1">
                      {s.description ? <p className="body text-[var(--ink-3)]">{s.description}</p> : null}
                      {s.sourcePath ? <p className="data mt-3 truncate text-[var(--ink-4)]">{s.sourcePath}</p> : null}
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
